import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { CodeSnippet, CodeSnippetSkeleton } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';
import './styles.css'; // see CSS below

function App() {
  const [url, setUrl] = useState(null);

  // Simulate async load of the webhook URL
  useEffect(() => {
    setTimeout(() => {
      setUrl('https://integrations.us-south.assistant.dev.watson.cloud/whatsapp');
    }, 3000);
  }, []);

  return (
    <div style={{ padding: '2rem', maxWidth: '600px' }}>
      <h2>WhatsApp Webhook</h2>

      {/* Before URL is available, we try to render a disabled CodeSnippet */}
      {!url ? (
        // You might expect a disabled CodeSnippet here...
        <CodeSnippet
          type="single"
          disabled={true}        // <-- no effect today
          feedbackText="Copied!"
          copyButtonDescription="Copy URL"
        >
          {''}
        </CodeSnippet>
      ) : (
        <CodeSnippet
          type="single"
          feedbackText="Copied!"
          copyButtonDescription="Copy URL"
        >
          {url}
        </CodeSnippet>
      )}
    </div>
  );
}

// Simple CSS override to grey out the container so you can see the 'disabled' intent
// (Carbon doesn’t apply any styles when you pass disabled to CodeSnippet today)
// styles.css
// --------------------------------
// .bx--snippet[disabled] {
//   background-color: #f4f4f4;
//   color: #8d8d8d;
// }
// --------------------------------

ReactDOM.render(<App />, document.getElementById('root'));
